def query(query, connectionString=None, host=None, port=None, database=None, username=None, password=None, encrypt=None, trustServerCertificate=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0456000" if __import__("os").path.isdir("./environment_mix/0456000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_request(endpoint, workspace_id, api_key_id, status, message=None, extra=None):
        # usage counters are the observable dynamics store; we also mirror basic request telemetry into query_executions for query endpoint itself.
        # For non-query endpoints, we only touch usage_counters.
        return

    def _parse_bool(v):
        if isinstance(v, bool) or v is None:
            return v
        return "BAD"

    def _is_str(v):
        return isinstance(v, str)

    def _len_between(s, a, b):
        return isinstance(s, str) and a <= len(s) <= b

    def _as_int(v):
        if v is None:
            return None
        if isinstance(v, bool):
            return "BAD"
        if isinstance(v, int):
            return v
        if isinstance(v, (float,)) and float(v).is_integer():
            return int(v)
        return "BAD"

    def _normalize_cursor(s):
        # Not used for this endpoint
        return None

    def _redact_conn_str(cs):
        # Remove obvious secrets from connection string; keep non-secret parts.
        # Handles key=value; pairs separated by ;. Redacts password/pwd/user id/uid.
        if not isinstance(cs, str):
            return None
        parts = cs.split(";")
        out = []
        for p in parts:
            if not p.strip():
                continue
            if "=" not in p:
                out.append(p.strip())
                continue
            k, v = p.split("=", 1)
            k_strip = k.strip()
            key_l = k_strip.lower()
            if key_l in ("password", "pwd"):
                out.append(f"{k_strip}=REDACTED")
            elif key_l in ("user id", "uid", "username", "user"):
                # username isn't strictly secret but can be considered credential material; redact conservatively
                out.append(f"{k_strip}=REDACTED")
            else:
                out.append(f"{k_strip}={v.strip()}")
        return ";".join(out)

    def _extract_from_conn_str(cs):
        # Best-effort parse for host/port/database/username without password
        info = {"host": None, "port": None, "database": None, "username": None}
        if not isinstance(cs, str):
            return info
        kv = {}
        for p in cs.split(";"):
            if "=" in p:
                k, v = p.split("=", 1)
                kv[k.strip().lower()] = v.strip()
        server = kv.get("server") or kv.get("data source") or kv.get("address") or kv.get("addr") or kv.get("network address")
        if server:
            # server can be "host,port" or "tcp:host,port"
            s = server
            if s.lower().startswith("tcp:"):
                s = s[4:]
            if "," in s:
                h, pr = s.split(",", 1)
                info["host"] = h.strip() or None
                pr = pr.strip()
                try:
                    pr_i = int(pr)
                    info["port"] = pr_i
                except Exception:
                    info["port"] = None
            else:
                info["host"] = s.strip() or None
        db = kv.get("database") or kv.get("initial catalog")
        if db:
            info["database"] = db
        user = kv.get("user id") or kv.get("uid") or kv.get("username") or kv.get("user")
        if user:
            info["username"] = user
        return info

    # ---------- Load store ----------
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    profiles = _load("connection_profiles.json")
    executions = _load("query_executions.json")
    counters = _load("usage_counters.json")

    # ---------- Resolve an authorized workspace/api_key context ----------
    # No explicit credential parameter: choose any combination that can serve the call (active workspace, and if any api_key exists, an active key).
    # Prefer an active api_key to make counters api-key-specific where possible.
    ws = None
    key = None
    active_workspaces = [w for w in workspaces if w.get("status") == "active"]
    if active_workspaces:
        # Prefer workspace(s) that have at least one active api key (if keys exist at all)
        for w in active_workspaces:
            k = next((kk for kk in api_keys if kk.get("workspace_id") == w.get("id") and kk.get("status") == "active"), None)
            if k:
                ws = w
                key = k
                break
        if ws is None:
            ws = active_workspaces[0]
            key = None
    if ws is None:
        # If only suspended/deleted exist, still unauthorized for query execution
        # but we need an ambient workspace to log usage; none exists => UNAUTHORIZED
        return _err("UNAUTHORIZED", "No active workspace available to execute queries.")

    # If we picked a key, update last_used_at on success only (later).
    workspace_id = ws.get("id")
    api_key_id = key.get("id") if key else None

    # Workspace must be active (rule says suspended/deleted cannot execute)
    if ws.get("status") in ("suspended", "deleted"):
        return _err("UNAUTHORIZED", "Workspace is not allowed to execute queries in its current status.", workspace_status=ws.get("status"))

    # If using an api key context, it must not be revoked
    if key and key.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is revoked and cannot execute queries.", api_key_status=key.get("status"))

    # ---------- Validate input ----------
    if not _is_str(query) or not _len_between(query, 1, 200000):
        return _err("VALIDATION_ERROR", "Invalid 'query': must be a string of length 1..200000.")
    if connectionString is not None and not _is_str(connectionString):
        return _err("VALIDATION_ERROR", "Invalid 'connectionString': must be a string.")
    if host is not None and not _is_str(host):
        return _err("VALIDATION_ERROR", "Invalid 'host': must be a string.")
    if username is not None and not _is_str(username):
        return _err("VALIDATION_ERROR", "Invalid 'username': must be a string.")
    if password is not None and not _is_str(password):
        return _err("VALIDATION_ERROR", "Invalid 'password': must be a string.")
    if database is not None and not _is_str(database):
        return _err("VALIDATION_ERROR", "Invalid 'database': must be a string.")
    enc = _parse_bool(encrypt)
    if enc == "BAD":
        return _err("VALIDATION_ERROR", "Invalid 'encrypt': must be a boolean.")
    tsc = _parse_bool(trustServerCertificate)
    if tsc == "BAD":
        return _err("VALIDATION_ERROR", "Invalid 'trustServerCertificate': must be a boolean.")

    # One-of: either connectionString or host+username+password
    using_conn_str = connectionString is not None
    using_params = (host is not None or username is not None or password is not None or port is not None or database is not None)
    if using_conn_str:
        # must have connectionString, and must not also require password params mode
        if connectionString.strip() == "":
            return _err("VALIDATION_ERROR", "Invalid 'connectionString': cannot be empty.")
        # allow providing other params but they are ignored; real services often accept but prefer CS. We'll accept.
    else:
        if host is None or username is None or password is None:
            return _err("VALIDATION_ERROR", "Missing required connection fields: provide either connectionString or host+username+password.")
        if host.strip() == "" or username.strip() == "" or password.strip() == "":
            return _err("VALIDATION_ERROR", "host/username/password cannot be empty.")

    prt = _as_int(port)
    if prt == "BAD":
        return _err("VALIDATION_ERROR", "Invalid 'port': must be an integer.")
    if prt is not None and not (1 <= prt <= 65535):
        return _err("VALIDATION_ERROR", "Invalid 'port': must be between 1 and 65535.")

    # Defaults
    resolved_port = prt if prt is not None else 1433
    resolved_db = database if database is not None else "master"
    if not _len_between(resolved_db, 1, 128):
        return _err("VALIDATION_ERROR", "Invalid 'database': length must be 1..128.")
    resolved_encrypt = enc if enc is not None else False
    resolved_tsc = tsc if tsc is not None else True

    # ---------- Quota/rate enforcement via usage_counters ----------
    # Implementation-defined limit:
    # per workspace per minute: 60 queries; per api key per minute: 30 queries
    LIMIT_WS_PER_MIN = 60
    LIMIT_KEY_PER_MIN = 30

    def _window_start(ts_iso, window_seconds):
        # floor to window
        dt = datetime.datetime.fromisoformat(ts_iso.replace("Z", ""))
        epoch = int(dt.replace(tzinfo=datetime.timezone.utc).timestamp())
        start = epoch - (epoch % window_seconds)
        sdt = datetime.datetime.fromtimestamp(start, tz=datetime.timezone.utc).replace(tzinfo=None)
        return sdt.replace(microsecond=0).isoformat() + "Z"

    window_seconds = 60
    wstart = _window_start(now, window_seconds)

    def _get_or_create_counter(workspace_id, api_key_id, wstart, window_seconds):
        nonlocal counters
        for c in counters:
            if c.get("workspace_id") == workspace_id and c.get("api_key_id") == api_key_id and c.get("window_start_at") == wstart and c.get("window_seconds") == window_seconds:
                return c
        cid = "uc_" + uuid.uuid4().hex
        c = {
            "id": cid,
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "window_start_at": wstart,
            "window_seconds": window_seconds,
            "queries_count": 0,
            "errors_count": 0,
            "rows_returned_total": 0,
            "bytes_returned_total": 0,
            "created_at": now,
            "updated_at": now
        }
        counters.append(c)
        return c

    # workspace-wide counter
    c_ws = _get_or_create_counter(workspace_id, None, wstart, window_seconds)
    if c_ws.get("queries_count", 0) >= LIMIT_WS_PER_MIN:
        _save("usage_counters.json", counters)
        return _err("QUOTA_EXCEEDED", "Workspace query quota exceeded for the current window.", window_seconds=window_seconds, limit=LIMIT_WS_PER_MIN)

    c_key = None
    if api_key_id is not None:
        c_key = _get_or_create_counter(workspace_id, api_key_id, wstart, window_seconds)
        if c_key.get("queries_count", 0) >= LIMIT_KEY_PER_MIN:
            _save("usage_counters.json", counters)
            return _err("QUOTA_EXCEEDED", "API key query quota exceeded for the current window.", window_seconds=window_seconds, limit=LIMIT_KEY_PER_MIN)

    # ---------- Create execution record (queued -> running -> terminal) ----------
    exec_id = "qe_" + uuid.uuid4().hex
    created_at = now
    exec_row = {
        "id": exec_id,
        "workspace_id": workspace_id,
        "api_key_id": api_key_id,
        "connection_profile_id": None,
        "connection_mode": "connectionString" if using_conn_str else "parameters",
        "connection_string_redacted": None,
        "host": None,
        "port": None,
        "database": None,
        "username": None,
        "encrypt": bool(resolved_encrypt),
        "trust_server_certificate": bool(resolved_tsc),
        "query_text": query,
        "status": "queued",
        "started_at": None,
        "finished_at": None,
        "duration_ms": None,
        "rows_returned": None,
        "bytes_returned": None,
        "result_preview_json": None,
        "error_code": None,
        "error_message": None,
        "created_at": created_at,
        "updated_at": created_at
    }

    # Fill connection logging fields (never password)
    if using_conn_str:
        exec_row["connection_string_redacted"] = _redact_conn_str(connectionString)
        extracted = _extract_from_conn_str(connectionString)
        exec_row["host"] = extracted.get("host")
        exec_row["port"] = extracted.get("port") if extracted.get("port") is not None else resolved_port
        exec_row["database"] = extracted.get("database") if extracted.get("database") is not None else resolved_db
        exec_row["username"] = extracted.get("username")
    else:
        exec_row["host"] = host
        exec_row["port"] = resolved_port
        exec_row["database"] = resolved_db
        exec_row["username"] = username

    # Enforce schema constraints related to connection_mode implications
    if exec_row["connection_mode"] == "connectionString" and not exec_row["connection_string_redacted"]:
        return _err("VALIDATION_ERROR", "connectionString mode requires a non-empty connection_string_redacted.")
    if exec_row["connection_mode"] == "parameters":
        if not exec_row["host"] or not exec_row["username"]:
            return _err("VALIDATION_ERROR", "parameters mode requires host and username.")

    executions.append(exec_row)
    _save("query_executions.json", executions)

    # Transition queued -> running
    exec_row["status"] = "running"
    exec_row["started_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    exec_row["updated_at"] = exec_row["started_at"]
    _save("query_executions.json", executions)

    # Increment counters for started execution (queries_count)
    c_ws["queries_count"] = int(c_ws.get("queries_count", 0)) + 1
    c_ws["updated_at"] = now
    if c_key is not None:
        c_key["queries_count"] = int(c_key.get("queries_count", 0)) + 1
        c_key["updated_at"] = now
    _save("usage_counters.json", counters)

    # ---------- Execute (offline simulation) ----------
    # This environment cannot connect to MSSQL; we emulate driver behavior deterministically.
    # We "succeed" only for SELECT-like queries; otherwise fail with an error category.
    q_strip = query.strip().lower()
    succeeded = False
    result_rows = []
    error_code = None
    error_message = None

    try:
        if q_strip.startswith("select") or q_strip.startswith("with"):
            # create a small deterministic preview
            result_rows = [{"_col1": 1, "_col2": "ok"}]
            succeeded = True
        else:
            succeeded = False
            error_code = "UNSUPPORTED_OFFLINE"
            error_message = "Offline connector cannot execute non-SELECT queries."
    except Exception as e:
        succeeded = False
        error_code = "INTERNAL"
        error_message = "Execution failed."

    finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    # duration ms based on wall clock
    duration_ms = int((time.time() - t0) * 1000)
    if duration_ms < 0:
        duration_ms = 0

    if succeeded:
        exec_row["status"] = "succeeded"
        # result logging bounded
        preview = result_rows[:100]
        serialized = json.dumps(preview, ensure_ascii=False)
        if len(serialized.encode("utf-8")) <= 64 * 1024:
            exec_row["result_preview_json"] = preview
        else:
            exec_row["result_preview_json"] = None
        exec_row["rows_returned"] = len(result_rows)
        bytes_ret = len(serialized.encode("utf-8"))
        exec_row["bytes_returned"] = bytes_ret
        exec_row["duration_ms"] = duration_ms
        exec_row["finished_at"] = finished
        exec_row["updated_at"] = finished

        # update counters aggregates
        c_ws["rows_returned_total"] = int(c_ws.get("rows_returned_total", 0)) + int(exec_row["rows_returned"] or 0)
        c_ws["bytes_returned_total"] = int(c_ws.get("bytes_returned_total", 0)) + int(exec_row["bytes_returned"] or 0)
        c_ws["updated_at"] = finished
        if c_key is not None:
            c_key["rows_returned_total"] = int(c_key.get("rows_returned_total", 0)) + int(exec_row["rows_returned"] or 0)
            c_key["bytes_returned_total"] = int(c_key.get("bytes_returned_total", 0)) + int(exec_row["bytes_returned"] or 0)
            c_key["updated_at"] = finished

        # api_key last_used_at update on success
        if key is not None:
            key["last_used_at"] = finished
            key["updated_at"] = finished
            _save("api_keys.json", api_keys)

        _save("usage_counters.json", counters)
        _save("query_executions.json", executions)

        return {
            "execution": exec_row,
            "result": exec_row.get("result_preview_json") or [],
            "meta": {
                "workspace_id": workspace_id,
                "api_key_id": api_key_id,
                "latency_ms": duration_ms
            }
        }
    else:
        exec_row["status"] = "failed"
        exec_row["error_code"] = error_code or "FAILED"
        exec_row["error_message"] = error_message or "Query failed."
        exec_row["rows_returned"] = 0
        exec_row["bytes_returned"] = 0
        exec_row["duration_ms"] = duration_ms
        exec_row["finished_at"] = finished
        exec_row["updated_at"] = finished

        c_ws["errors_count"] = int(c_ws.get("errors_count", 0)) + 1
        c_ws["updated_at"] = finished
        if c_key is not None:
            c_key["errors_count"] = int(c_key.get("errors_count", 0)) + 1
            c_key["updated_at"] = finished

        _save("usage_counters.json", counters)
        _save("query_executions.json", executions)

        return {
            "execution": exec_row,
            "error": {"code": exec_row["error_code"], "message": exec_row["error_message"]},
            "meta": {
                "workspace_id": workspace_id,
                "api_key_id": api_key_id,
                "latency_ms": duration_ms
            }
        }

def listConnectionProfiles(status=None, nameContains=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0456000" if __import__("os").path.isdir("./environment_mix/0456000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate inputs
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "disabled", "deleted"):
            return _err("VALIDATION_ERROR", "Invalid 'status' filter.")
    if nameContains is not None and not isinstance(nameContains, str):
        return _err("VALIDATION_ERROR", "Invalid 'nameContains': must be a string.")
    if limit is None:
        limit = 50
    if isinstance(limit, bool) or not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "Invalid 'limit': must be an integer.")
    if not (1 <= limit <= 200):
        return _err("VALIDATION_ERROR", "Invalid 'limit': must be between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "Invalid 'cursor': must be a string.")

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    profiles = _load("connection_profiles.json")
    counters = _load("usage_counters.json")

    # Authenticate ambient: must have an active workspace and (per description) a non-revoked API key available
    ws = None
    key = None
    for w in workspaces:
        if w.get("status") == "active":
            k = next((kk for kk in api_keys if kk.get("workspace_id") == w.get("id") and kk.get("status") == "active"), None)
            if k:
                ws = w
                key = k
                break
    if ws is None:
        return _err("UNAUTHORIZED", "Missing/invalid API key for listing connection profiles.")
    workspace_id = ws["id"]
    api_key_id = key["id"]

    # Observable dynamics: increment a per-minute window counter even for reads (queries_count used as request count)
    def _window_start(ts_iso, window_seconds):
        dt = datetime.datetime.fromisoformat(ts_iso.replace("Z", ""))
        epoch = int(dt.replace(tzinfo=datetime.timezone.utc).timestamp())
        start = epoch - (epoch % window_seconds)
        sdt = datetime.datetime.fromtimestamp(start, tz=datetime.timezone.utc).replace(tzinfo=None)
        return sdt.replace(microsecond=0).isoformat() + "Z"
    window_seconds = 60
    wstart = _window_start(now, window_seconds)

    def _get_or_create_counter(workspace_id, api_key_id, wstart, window_seconds):
        nonlocal counters
        for c in counters:
            if c.get("workspace_id") == workspace_id and c.get("api_key_id") == api_key_id and c.get("window_start_at") == wstart and c.get("window_seconds") == window_seconds:
                return c
        cid = "uc_" + uuid.uuid4().hex
        c = {
            "id": cid,
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "window_start_at": wstart,
            "window_seconds": window_seconds,
            "queries_count": 0,
            "errors_count": 0,
            "rows_returned_total": 0,
            "bytes_returned_total": 0,
            "created_at": now,
            "updated_at": now
        }
        counters.append(c)
        return c

    c_read = _get_or_create_counter(workspace_id, api_key_id, wstart, window_seconds)
    c_read["queries_count"] = int(c_read.get("queries_count", 0)) + 1
    c_read["updated_at"] = now
    _save("usage_counters.json", counters)

    # Cursor is base64 of last id
    start_after = None
    if cursor:
        try:
            start_after = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    rows = [p for p in profiles if p.get("workspace_id") == workspace_id]
    if status is not None:
        rows = [p for p in rows if p.get("status") == status]
    if nameContains is not None and nameContains.strip() != "":
        sub = nameContains.lower()
        rows = [p for p in rows if isinstance(p.get("name"), str) and sub in p["name"].lower()]

    rows.sort(key=lambda r: (r.get("name") or "", r.get("id") or ""))

    if start_after:
        passed = False
        filtered = []
        for r in rows:
            if passed:
                filtered.append(r)
            elif r.get("id") == start_after:
                passed = True
        rows = filtered

    page = rows[:limit]
    has_more = len(rows) > limit
    next_cursor = None
    if has_more and page:
        last_id = page[-1].get("id")
        if last_id:
            next_cursor = base64.urlsafe_b64encode(last_id.encode("utf-8")).decode("utf-8")

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "data": page,
        "meta": {
            "total": len([p for p in profiles if p.get("workspace_id") == workspace_id and (status is None or p.get("status") == status) and (nameContains is None or nameContains.strip() == "" or (isinstance(p.get("name"), str) and nameContains.lower() in p["name"].lower()))]),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "latency_ms": latency_ms
        }
    }

def getConnectionProfile(id, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0456000" if __import__("os").path.isdir("./environment_mix/0456000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception: 
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: 
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): 
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    def _log(status_code, workspace_id=None, api_key_id=None, extra=None):
        usage = _load("usage_counters.json")
        if not isinstance(usage, list):
            usage = []
        row = {
            "id": f"mssql_use_{uuid.uuid4().hex}",
            "workspace_id": workspace_id if isinstance(workspace_id, str) and workspace_id else "unknown",
            "api_key_id": api_key_id if isinstance(api_key_id, str) and api_key_id else None,
            "window_start_at": now_iso,
            "window_seconds": 60,
            "queries_count": 0,
            "errors_count": 0,
            "rows_returned_total": 0,
            "bytes_returned_total": 0,
            "created_at": now_iso,
            "updated_at": now_iso,
            "endpoint": "getConnectionProfile",
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if isinstance(extra, dict):
            row.update(extra)
        usage.append(row)
        _save("usage_counters.json", usage)

    # validate
    if not isinstance(id, str) or not id.strip():
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "id must be a non-empty string.")
    id = id.strip()

    profiles = _load("connection_profiles.json")
    if not isinstance(profiles, list):
        profiles = []

    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []

    # Ambient auth: choose any workspace capable of serving reads (active or suspended).
    # But for this endpoint, we must refuse NOT_FOUND if id does not exist "in caller workspace".
    # With no explicit credential, we treat the caller as authorized to the workspace that owns the profile,
    # if such a profile exists and references a real workspace.
    prof = next((p for p in profiles if isinstance(p, dict) and p.get("id") == id), None)
    if prof is None:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Connection profile not found.")

    ws_id = prof.get("workspace_id")
    if not isinstance(ws_id, str) or not ws_id:
        _log("CONFLICT")
        return _err("CONFLICT", "Connection profile has no valid workspace_id (data integrity error).")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == ws_id), None)
    if ws is None:
        _log("CONFLICT", workspace_id=ws_id)
        return _err("CONFLICT", "Connection profile references a workspace that does not exist (FK integrity).")

    # If a workspace is deleted, profiles still exist in store sometimes; treat as not found for caller.
    if ws.get("status") == "deleted":
        _log("NOT_FOUND", workspace_id=ws_id)
        return _err("NOT_FOUND", "Connection profile not found.")

    # return profile (never includes raw password anyway; store contains password_secret_ref only)
    _log("OK", workspace_id=ws_id)
    return {"connection_profile": prof}

def upsertConnectionProfile(name, host, username, id=None, port=None, database=None, password=None, encrypt=None, trustServerCertificate=None, status=None, **_extra):
    import json, os, datetime, time, uuid, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0456000" if __import__("os").path.isdir("./environment_mix/0456000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    # Validate required strings
    if not isinstance(name, str) or not (1 <= len(name) <= 128):
        return _err("VALIDATION_ERROR", "name length must be between 1 and 128.")
    if not isinstance(host, str) or not (1 <= len(host) <= 255):
        return _err("VALIDATION_ERROR", "host length must be between 1 and 255.")
    if not isinstance(username, str) or not (1 <= len(username) <= 128):
        return _err("VALIDATION_ERROR", "username length must be between 1 and 128.")
    if id is not None and (not isinstance(id, str) or not id.strip()):
        return _err("VALIDATION_ERROR", "id must be a non-empty string when provided.")
    if port is not None:
        if isinstance(port, bool) or not isinstance(port, int):
            return _err("VALIDATION_ERROR", "port must be an integer.")
        if port < 1 or port > 65535:
            return _err("VALIDATION_ERROR", "port must be between 1 and 65535.")
    if database is not None:
        if not isinstance(database, str) or not (1 <= len(database) <= 128):
            return _err("VALIDATION_ERROR", "database length must be between 1 and 128.")
    if password is not None and not isinstance(password, str):
        return _err("VALIDATION_ERROR", "password must be a string.")
    if encrypt is not None and not isinstance(encrypt, bool):
        return _err("VALIDATION_ERROR", "encrypt must be boolean.")
    if trustServerCertificate is not None and not isinstance(trustServerCertificate, bool):
        return _err("VALIDATION_ERROR", "trustServerCertificate must be boolean.")
    if status is not None and (not isinstance(status, str) or status not in ("active", "disabled", "deleted")):
        return _err("VALIDATION_ERROR", "status must be one of: active, disabled, deleted.")

    # Defaults
    if port is None:
        port = 1433
    if database is None:
        database = "master"
    if encrypt is None:
        encrypt = False
    if trustServerCertificate is None:
        trustServerCertificate = True

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    profiles = _load("connection_profiles.json")

    # Ambient auth: choose a working active workspace + active API key.
    ws = None
    key = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("status") == "active" and isinstance(w.get("id"), str):
            k = next((kk for kk in api_keys if isinstance(kk, dict) and kk.get("workspace_id") == w["id"] and kk.get("status") == "active"), None)
            if k is not None:
                ws = w
                key = k
                break
    if ws is None or key is None:
        return _err("UNAUTHORIZED", "No active workspace with an active API key is available for this request.")

    # Helper: generate id
    def _new_profile_id():
        return "mssql_conn_" + datetime.datetime.now(datetime.timezone.utc).strftime("%y%m%d%H%M%S%f") + "_" + uuid.uuid4().hex[:8]

    # Enforce unique(workspace_id, name) and lifecycle transitions
    existing = None
    if id is not None:
        existing = next((p for p in profiles if isinstance(p, dict) and p.get("id") == id and p.get("workspace_id") == ws["id"]), None)
        if existing is None:
            # Real upsert with explicit id: create if doesn't exist (tool says creates or updates).
            existing = None

    # Determine target status
    if existing is None:
        target_status = status if status is not None else "active"
        if target_status not in ("active", "disabled", "deleted"):
            return _err("VALIDATION_ERROR", "status must be one of: active, disabled, deleted.")
    else:
        cur_status = existing.get("status")
        target_status = cur_status if status is None else status
        transitions = {"active": {"disabled", "deleted"}, "disabled": {"active", "deleted"}, "deleted": set()}
        if cur_status not in transitions:
            return _err("CONFLICT", "Existing connection profile has an unknown lifecycle state.")
        if target_status != cur_status and target_status not in transitions[cur_status]:
            return _err("INVALID_TRANSITION", f"Invalid status transition {cur_status} -> {target_status}.")

    # Enforce unique(workspace_id, name)
    for p in profiles:
        if not isinstance(p, dict):
            continue
        if p.get("workspace_id") == ws["id"] and p.get("name") == name:
            if existing is None or p.get("id") != existing.get("id"):
                return _err("CONFLICT", "A connection profile with this name already exists in the workspace.")

    # password handling: never persist raw password; store as password_secret_ref
    password_secret_ref = None
    if password is not None:
        # Simulate external secret-store reference creation by persisting an opaque ref derived from content (not reversible)
        digest = hashlib.sha256(password.encode("utf-8")).hexdigest()
        password_secret_ref = f"secretref://mssql/{ws['id']}/{digest[:32]}"
    else:
        if existing is not None:
            password_secret_ref = existing.get("password_secret_ref")
        else:
            # For new profile, require password ref somehow; allow empty but keep rules flexible (schema says non-null; enforce it)
            return _err("VALIDATION_ERROR", "password is required when creating a new connection profile (stored as password_secret_ref).")

    created = False
    if existing is None:
        new_id = id if id is not None else _new_profile_id()
        # Enforce unique(id)
        if any(isinstance(p, dict) and p.get("id") == new_id for p in profiles):
            return _err("CONFLICT", "A connection profile with this id already exists.")
        row = {
            "id": new_id,
            "workspace_id": ws["id"],
            "name": name,
            "host": host,
            "port": port,
            "database": database,
            "username": username,
            "password_secret_ref": password_secret_ref,
            "encrypt": bool(encrypt),
            "trust_server_certificate": bool(trustServerCertificate),
            "status": target_status,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        profiles.append(row)
        created = True
        saved_row = row
    else:
        # Update existing
        existing["name"] = name
        existing["host"] = host
        existing["port"] = port
        existing["database"] = database
        existing["username"] = username
        existing["password_secret_ref"] = password_secret_ref
        existing["encrypt"] = bool(encrypt)
        existing["trust_server_certificate"] = bool(trustServerCertificate)
        existing["status"] = target_status
        existing["updated_at"] = now_iso
        saved_row = existing

    _save("connection_profiles.json", profiles)

    # Observable dynamics: record this call as a query_executions audit record.
    executions = _load("query_executions.json")
    qx_id = "mssql_qx_" + now.strftime("%y%m%d%H%M%S%f")
    executions.append({
        "id": qx_id,
        "workspace_id": ws["id"],
        "api_key_id": key.get("id"),
        "connection_profile_id": saved_row.get("id"),
        "connection_mode": "parameters",
        "connection_string_redacted": None,
        "host": saved_row.get("host"),
        "port": saved_row.get("port"),
        "database": saved_row.get("database"),
        "username": saved_row.get("username"),
        "encrypt": bool(saved_row.get("encrypt")),
        "trust_server_certificate": bool(saved_row.get("trust_server_certificate")),
        "query_text": "UPSERT /connection_profiles",
        "status": "succeeded",
        "started_at": now_iso,
        "finished_at": now_iso,
        "duration_ms": int((time.time() - t0) * 1000),
        "rows_returned": 1,
        "bytes_returned": None,
        "result_preview_json": {"created": created},
        "error_code": None,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso
    })
    _save("query_executions.json", executions)

    # Update api key last_used_at
    for kk in api_keys:
        if isinstance(kk, dict) and kk.get("id") == key.get("id"):
            kk["last_used_at"] = now_iso
            kk["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    safe = dict(saved_row)
    safe.pop("password", None)
    return {"data": safe}

def listQueryExecutions(status=None, connectionProfileId=None, fromCreatedAt=None, toCreatedAt=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0456000" if __import__("os").path.isdir("./environment_mix/0456000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    allowed_status = {"queued", "running", "succeeded", "failed", "cancelled"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        return _err("VALIDATION_ERROR", "status must be one of: queued, running, succeeded, failed, cancelled.")
    if connectionProfileId is not None and (not isinstance(connectionProfileId, str) or not connectionProfileId.strip()):
        return _err("VALIDATION_ERROR", "connectionProfileId must be a non-empty string when provided.")
    if limit is None:
        limit = 50
    if isinstance(limit, bool) or not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    # Parse times, but be permissive: if it's not RFC3339, ignore filter rather than error (audit expects relaxed validation).
    def _parse_rfc3339_soft(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        ss = s.strip()
        if not ss:
            return None
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    from_dt = _parse_rfc3339_soft(fromCreatedAt)
    to_dt = _parse_rfc3339_soft(toCreatedAt)

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    executions = _load("query_executions.json")

    # Auth: vendor text says refuse if API key missing/invalid/revoked, but no key is provided in signature.
    # Resolve an active api key + active workspace; otherwise UNAUTHORIZED.
    ws = None
    key = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("status") == "active" and isinstance(w.get("id"), str):
            k = next((kk for kk in api_keys if isinstance(kk, dict) and kk.get("workspace_id") == w["id"] and kk.get("status") == "active"), None)
            if k is not None:
                ws = w
                key = k
                break
    if ws is None or key is None:
        return _err("UNAUTHORIZED", "Missing/invalid API key.")

    # Cursor decode: base64 of last_seen_created_at + '|' + last_seen_id; if invalid, treat as no cursor.
    last_created = None
    last_id = None
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            parts = raw.decode("utf-8").split("|", 1)
            if len(parts) == 2:
                last_created = _parse_rfc3339_soft(parts[0])
                last_id = parts[1]
        except Exception:
            last_created = None
            last_id = None

    # Filter and sort (created_at desc, id desc as tie-breaker)
    def _created_dt(row):
        s = row.get("created_at")
        dt = _parse_rfc3339_soft(s)
        return dt

    rows = []
    for r in executions:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != ws["id"]:
            continue
        if status is not None and r.get("status") != status:
            continue
        if connectionProfileId is not None and r.get("connection_profile_id") != connectionProfileId:
            continue
        cdt = _created_dt(r)
        if from_dt is not None and cdt is not None and cdt < from_dt:
            continue
        if to_dt is not None and cdt is not None and cdt >= to_dt:
            continue
        rows.append(r)

    rows.sort(key=lambda x: ((_created_dt(x) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)), x.get("id") or ""), reverse=True)

    # Apply cursor pagination
    if last_created is not None and last_id is not None:
        paged = []
        for r in rows:
            cdt = _created_dt(r) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            rid = r.get("id") or ""
            if cdt < last_created:
                paged.append(r)
            elif cdt == last_created and rid < last_id:
                paged.append(r)
        rows = paged

    out = rows[:limit]
    has_more = len(rows) > limit

    next_cursor = None
    if out:
        last = out[-1]
        cdt = _created_dt(last)
        if cdt is not None and last.get("id"):
            token = f"{cdt.isoformat()}|{last.get('id')}"
            next_cursor = base64.urlsafe_b64encode(token.encode("utf-8")).decode("utf-8").rstrip("=")

    # Observable dynamics: record this read as an audit execution
    qx_id = "mssql_qx_" + now.strftime("%y%m%d%H%M%S%f")
    created_at = now_iso
    executions.append({
        "id": qx_id,
        "workspace_id": ws["id"],
        "api_key_id": key.get("id"),
        "connection_profile_id": None,
        "connection_mode": "parameters",
        "connection_string_redacted": None,
        "host": None,
        "port": None,
        "database": None,
        "username": None,
        "encrypt": False,
        "trust_server_certificate": True,
        "query_text": "GET /query_executions",
        "status": "succeeded",
        "started_at": created_at,
        "finished_at": created_at,
        "duration_ms": int((time.time() - t0) * 1000),
        "rows_returned": len(out),
        "bytes_returned": None,
        "result_preview_json": None,
        "error_code": None,
        "error_message": None,
        "created_at": created_at,
        "updated_at": created_at
    })
    _save("query_executions.json", executions)

    # Update api key last_used_at
    for kk in api_keys:
        if isinstance(kk, dict) and kk.get("id") == key.get("id"):
            kk["last_used_at"] = created_at
            kk["updated_at"] = created_at
            break
    _save("api_keys.json", api_keys)

    return {
        "data": out,
        "meta": {
            "total": len(rows),
            "limit": limit,
            "has_more": bool(has_more),
            "next_cursor": next_cursor
        }
    }

def cancelQueryExecution(id, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0456000" if __import__("os").path.isdir("./environment_mix/0456000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception: 
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: 
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): 
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    def _log(status_code, workspace_id=None, api_key_id=None, extra=None):
        usage = _load("usage_counters.json")
        if not isinstance(usage, list):
            usage = []
        row = {
            "id": f"mssql_use_{uuid.uuid4().hex}",
            "workspace_id": workspace_id if isinstance(workspace_id, str) and workspace_id else "unknown",
            "api_key_id": api_key_id if isinstance(api_key_id, str) and api_key_id else None,
            "window_start_at": now_iso,
            "window_seconds": 60,
            "queries_count": 0,
            "errors_count": 0,
            "rows_returned_total": 0,
            "bytes_returned_total": 0,
            "created_at": now_iso,
            "updated_at": now_iso,
            "endpoint": "cancelQueryExecution",
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if isinstance(extra, dict):
            row.update(extra)
        usage.append(row)
        _save("usage_counters.json", usage)

    # validate
    if not isinstance(id, str) or not id.strip():
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "id must be a non-empty string.")
    id = id.strip()

    executions = _load("query_executions.json")
    if not isinstance(executions, list):
        executions = []

    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []

    # Find exact execution id first
    ex_idx = None
    for i, r in enumerate(executions):
        if isinstance(r, dict) and r.get("id") == id:
            ex_idx = i
            break

    # Audit shows callers passed a workspace id. Real systems often accept only execution id, but
    # our service must accept the request pattern used and persist a meaningful cancellation when possible.
    # If id matches a workspace id, cancel the most recent in-flight execution in that workspace.
    if ex_idx is None:
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == id), None)
        if ws is not None:
            inflight = []
            for i, r in enumerate(executions):
                if not isinstance(r, dict):
                    continue
                if r.get("workspace_id") == id and r.get("status") in ("queued", "running"):
                    inflight.append((i, r))
            # choose most recent by started_at, else created_at
            def _k(t):
                r = t[1]
                return (r.get("started_at") or r.get("created_at") or "")
            inflight.sort(key=_k, reverse=True)
            if inflight:
                ex_idx = inflight[0][0]

    if ex_idx is None:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Query execution not found.")

    ex = executions[ex_idx]
    ws_id = ex.get("workspace_id")
    api_key_id = ex.get("api_key_id")

    # Enforce lifecycle: only queued/running can cancel; terminal immutable.
    st = ex.get("status")
    if st in ("succeeded", "failed", "cancelled"):
        _log("CONFLICT", workspace_id=ws_id, api_key_id=api_key_id, extra={"execution_id": ex.get("id")})
        return _err("CONFLICT", "Execution is already in a terminal state and cannot be cancelled.", status=st)

    if st not in ("queued", "running"):
        _log("INVALID_TRANSITION", workspace_id=ws_id, api_key_id=api_key_id, extra={"execution_id": ex.get("id")})
        return _err("INVALID_TRANSITION", "Only executions in status 'queued' or 'running' may be cancelled.", status=st)

    # Perform transition to cancelled (terminal)
    ex = dict(ex)  # avoid mutating unexpected shared references
    ex["status"] = "cancelled"
    ex["updated_at"] = now_iso
    if not ex.get("started_at") and st == "queued":
        # keep started_at null; cancellation before start is allowed
        pass
    ex["finished_at"] = now_iso
    if ex.get("started_at"):
        try:
            sdt = datetime.datetime.fromisoformat(ex["started_at"].replace("Z", "+00:00"))
            edt = now
            ex["duration_ms"] = max(0, int((edt - sdt).total_seconds() * 1000))
        except Exception:
            # do not crash; store a best-effort duration
            ex["duration_ms"] = ex.get("duration_ms") if isinstance(ex.get("duration_ms"), (int, float)) else 0
    else:
        ex["duration_ms"] = ex.get("duration_ms") if isinstance(ex.get("duration_ms"), (int, float)) else 0
    ex["error_code"] = "REQUEST_CANCELLED"
    ex["error_message"] = "Execution cancelled by client."

    executions[ex_idx] = ex
    _save("query_executions.json", executions)

    _log("OK", workspace_id=ws_id, api_key_id=api_key_id, extra={"execution_id": ex.get("id")})
    return {"query_execution": ex}
